// A drill restores a backup into a separate test database and checks every table. RPO: the backup was at most RPOHours
// old when tested (how much data could be lost); RTO: the restore finished within RTOHours (how long recovery takes).
$rpoLimit=(float)$settings['RPOHours'];$rtoLimit=(float)$settings['RTOHours'];
$hoursText=fn($h)=>$h===null?'—':($h<1?round($h*60).' min':($h<48?rtrim(rtrim(number_format($h,1),'0'),'.').' h':round($h/24,1).' days'));
$chip=fn($ok,$label,$why)=>$ok===null?'<span class="text-slate-400">—</span>':'<span title="'.drh($why).'" class="inline-flex items-center gap-1 px-2 py-1 rounded-lg text-[11px] font-black whitespace-nowrap '.($ok?'bg-green-50 text-green-700':'bg-red-50 text-red-700').'">'.($ok?'✓':'✕').' '.$label.' '.($ok?'met':'missed').'</span>';
?>
<h2 class="text-xl font-black mt-10 mb-1">Documented restoration drills</h2>
<p class="text-sm text-slate-500 mb-4">Each drill restores a backup into a separate test database and checks it. <b>RPO</b> is met when the backup was at most <?=drh($hoursText($rpoLimit))?> old when tested (how much data could be lost); <b>RTO</b> when the restore finished within <?=drh($hoursText($rtoLimit))?> (how long recovery takes). Point at a result for details.</p>
<div data-pager="drills" data-pager-items="tbody > tr" data-pager-search="Search drill no., backup file, who ran it or notes..." class="overflow-x-auto bg-white border rounded-2xl">
<table class="no-datatable w-full text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="p-4">Drill</th><th class="p-4">Backup tested</th><th class="p-4">Result</th><th class="p-4">Restore time</th><th class="p-4">Checked</th><th class="p-4">RPO / RTO</th><th class="p-4">Run</th></tr></thead><tbody>
<?php foreach($drills as $d):
    $age=$d['BackupAgeHours']===null?null:(float)$d['BackupAgeHours'];$secs=$d['RestoreDurationSeconds']===null?null:(float)$d['RestoreDurationSeconds'];
    $rpo=$d['RPOCompliant']===null?null:(bool)$d['RPOCompliant'];$rto=$d['RTOCompliant']===null?null:(bool)$d['RTOCompliant'];
    $backupLabel='#'.$d['BackupID'].' · '.date('M j, Y',strtotime($d['BackupCreatedAt']));
?>
<tr class="border-t align-top" data-filter-outcome="<?=drh($d['Status'])?>" data-filter-rpo="<?=$rpo===null?'':($rpo?'RPO met':'RPO missed')?>" data-filter-rto="<?=$rto===null?'':($rto?'RTO met':'RTO missed')?>" data-filter-backup="<?=drh($backupLabel)?>">
<td class="p-4 font-black whitespace-nowrap">#<?=drh($d['DrillID'])?></td>
<td class="p-4 min-w-[14rem] max-w-xs"><p class="font-bold truncate" title="<?=drh($d['FileName'])?>">#<?=drh($d['BackupID'])?> · <?=drh($d['FileName'])?></p><p class="text-xs text-slate-500 mt-0.5"><?=drh($d['BackupType'])?> backup made <?=date('M j, Y g:i A',strtotime($d['BackupCreatedAt']))?><?=$age!==null?' · '.drh($hoursText($age)).' old when tested':''?></p></td>
<td class="p-4"><span class="font-black <?=$d['Status']==='Passed'?'text-green-700':($d['Status']==='Failed'?'text-red-600':'text-amber-600')?>"><?=drh($d['Status'])?></span><?php if(trim((string)$d['ValidationNotes'])!==''):?><p class="text-[11px] text-slate-400 mt-0.5 max-w-[12rem] truncate" title="<?=drh($d['ValidationNotes'])?>"><?=drh($d['ValidationNotes'])?></p><?php endif;?></td>
<td class="p-4 whitespace-nowrap"><?=$secs===null?'—':drh(number_format($secs,2)).' sec'?><p class="text-[11px] text-slate-400">limit <?=drh($hoursText($rtoLimit))?></p></td>
<td class="p-4 whitespace-nowrap"><?=$d['TableCount']!==null?(int)$d['TableCount'].' tables<p class="text-[11px] text-slate-400">'.number_format((int)$d['RowCount']).' rows</p>':'—'?></td>
<td class="p-4"><div class="flex flex-wrap gap-1.5"><?=$chip($rpo,'RPO',$age===null?'':'The backup was '.$hoursText($age).' old when tested; the limit is '.$hoursText($rpoLimit).'.')?><?=$chip($rto,'RTO',$secs===null?'':'The restore took '.number_format($secs,2).' seconds; the limit is '.$hoursText($rtoLimit).'.')?></div></td>
<td class="p-4 whitespace-nowrap"><?=date('M j, Y g:i A',strtotime($d['StartedAt']))?><?php if($d['RunBy']):?><p class="text-[11px] text-slate-400">by <?=drh($d['RunBy'])?></p><?php endif;?></td>
</tr>
<?php endforeach;?><?php if(!$drills):?><tr><td colspan="7" class="p-10 text-center text-slate-500">No restoration drill has been documented yet. Run one from a backup above.</td></tr><?php endif;?></tbody></table></div>
